<?php require '../common.php';startpage('Online Bus Ticket Booking');nav('<a href="index.php">Search buses</a><a href="admin.php">Admin</a><a href="bookings.php">Booking history</a><a href="comments.php">Comments</a>');$from=$_GET['from']??'';$to=$_GET['to']??'';$s=$conn->prepare("SELECT * FROM buses WHERE (?='' OR origin LIKE CONCAT('%',?,'%')) AND (?='' OR destination LIKE CONCAT('%',?,'%'))");$s->bind_param('ssss',$from,$from,$to,$to);$s->execute();$rs=$s->get_result();?><form><input name="from" placeholder="From" value="<?=e($from)?>" required><input name="to" placeholder="To" value="<?=e($to)?>" required><button>Search</button></form><table><tr><th>Bus</th><th>Category</th><th>Route</th><th>Date/time</th><th>Price</th><th>Seats</th><th>Book</th></tr><?php while($b=$rs->fetch_assoc()):?><tr><td><?=e($b['bus_name'])?></td><td><?=e($b['category'])?></td><td><?=e($b['origin'])?> → <?=e($b['destination'])?></td><td><?=$b['travel_date']?> <?=$b['departure_time']?></td><td>₹<?=$b['price']?></td><td><?=$b['available_seats']?></td><td><a href="book.php?id=<?=$b['id']?>">Book</a></td></tr><?php endwhile;?></table><?php endpage();?>